using System.Collections.Generic;
using UnityEngine;
using TMPro;

namespace PartyTaxes
{
    public enum PTButtonStyle { Paper, Wax }

    /// <summary>
    /// The paper-and-ink look shared by every screen: ink colours, fonts and sprites, loaded once from
    /// Resources/PartyTaxes/UI. Fonts are OFL (licences beside them in Fonts/); the art is generated by
    /// Tools/UIArt/generate_ui_art.py. Anything missing falls back to TMP's default font and flat paper
    /// colours, so the UI still works (and stays readable) without the assets.
    /// </summary>
    public static class PTUITheme
    {
        private const string ArtPath = "PartyTaxes/UI/";
        private const string FontPath = "PartyTaxes/UI/Fonts/";

        // ── Colours ───────────────────────────────────────────────────
        public static readonly Color Ink        = new Color(0.17f, 0.11f, 0.08f, 1f);
        public static readonly Color InkOff     = new Color(0.17f, 0.11f, 0.08f, 0.38f);
        public static readonly Color InkRed     = new Color(0.56f, 0.11f, 0.11f, 1f);
        public static readonly Color WaxText    = new Color(0.96f, 0.91f, 0.80f, 1f);
        public static readonly Color WaxTextOff = new Color(0.96f, 0.91f, 0.80f, 0.45f);
        public static readonly Color PaperFlat  = new Color(0.91f, 0.84f, 0.68f, 0.97f);           // used when the art is missing
        public static readonly Color WaxFlat    = new Color(0.49f, 0.08f, 0.09f, 1f);
        public static readonly Color Backdrop   = new Color(0.10f, 0.06f, 0.03f, 0.88f);           // tints the vignette behind full-screen documents
        public static readonly Color StampRed   = new Color(0.56f, 0.11f, 0.11f, 0.85f);
        public static readonly Color StampGreen = new Color(0.18f, 0.36f, 0.16f, 0.85f);
        public static readonly Color LedgerRule = new Color(0.56f, 0.11f, 0.11f, 0.35f);

        // Rich-text inks for <color=...> tags, dark enough to read on parchment
        public const string RedInk    = "#8E1B1B";                                                    // losses, theft, danger
        public const string GoldInk   = "#8A6212";                                                    // gold, unlocks, traits
        public const string GreenInk  = "#2E5A2A";                                                    // healing
        public const string BlueInk   = "#23466B";                                                    // party names
        public const string PurpleInk = "#5A2D6E";                                                    // death and dark magic
        public const string BrownInk  = "#9A5A12";                                                    // cowardice
        public const string FadedInk  = "#6B5A48";                                                    // hints and small print

        public static string Tint(string text, string hex) => "<color=" + hex + ">" + text + "</color>";

        // ── Sprites (9-slice borders in texture pixels; must match generate_ui_art.py) ──
        public static Sprite PaperPanel => LoadSprite("PaperPanel", 128f);
        public static Sprite PaperSlip  => LoadSprite("PaperSlip", 40f);
        public static Sprite WaxSlip    => LoadSprite("WaxSlip", 40f);
        public static Sprite Stamp      => LoadSprite("Stamp", 56f);
        public static Sprite InkDivider => LoadSprite("InkDivider", 0f);
        public static Sprite WaxSeal    => LoadSprite("WaxSeal", 0f);
        public static Sprite Coin       => LoadSprite("Coin", 0f);
        public static Sprite Vignette   => LoadSprite("Vignette", 0f);

        private static readonly Dictionary<string, Sprite> sprites = new Dictionary<string, Sprite>();

        private static Sprite LoadSprite(string name, float border)
        {
            Sprite sprite;
            if (sprites.TryGetValue(name, out sprite) && sprite != null) return sprite;
            Texture2D texture = Resources.Load<Texture2D>(ArtPath + name);
            sprite = texture == null ? null : Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), new Vector2(0.5f, 0.5f),
                                                            100f, 0, SpriteMeshType.FullRect, new Vector4(border, border, border, border));
            sprites[name] = sprite;
            return sprite;
        }

        // ── Fonts ─────────────────────────────────────────────────────
        private static TMP_FontAsset body, heading, title;

        /// Crimson Text, with real bold and italic faces for <b> and <i>: everything you read.
        public static TMP_FontAsset Body
        {
            get
            {
                if (body == null)
                {
                    body = CreateFont("CrimsonText-Regular");
                    if (body != null && body.fontWeightTable != null && body.fontWeightTable.Length > 7)
                    {
                        body.fontWeightTable[7].regularTypeface = CreateFont("CrimsonText-Bold");    // <b> uses the bold face, not faux bold
                        body.fontWeightTable[4].italicTypeface = CreateFont("CrimsonText-Italic");
                    }
                }
                return body;
            }
        }

        /// IM Fell English SC: headers and HUD labels, like an old printed broadsheet.
        public static TMP_FontAsset Heading => heading != null ? heading : (heading = CreateFont("IMFellEnglishSC-Regular"));

        /// Pirata One, a legible blackletter: royal titles only (big sizes).
        public static TMP_FontAsset Title => title != null ? title : (title = CreateFont("PirataOne-Regular"));

        /// A dynamic SDF font asset made at runtime from a TTF in Resources (so no editor step is needed).
        private static TMP_FontAsset CreateFont(string file)
        {
            Font font = Resources.Load<Font>(FontPath + file);
            if (font == null) return null;
            TMP_FontAsset asset = TMP_FontAsset.CreateFontAsset(font);
            if (asset == null) return null;
            asset.name = file;
            if (TMP_Settings.defaultFontAsset != null)
            {
                asset.fallbackFontAssetTable = new List<TMP_FontAsset> { TMP_Settings.defaultFontAsset };   // symbols the old fonts lack (e.g. arrows)
            }
            return asset;
        }

        /// Sets a text's font if that font loaded; otherwise it keeps TMP's default.
        public static void SetFont(TMP_Text text, TMP_FontAsset font)
        {
            if (text != null && font != null) text.font = font;
        }

        public static Color ButtonText(PTButtonStyle style, bool enabled)
        {
            if (style == PTButtonStyle.Wax) return enabled ? WaxText : WaxTextOff;
            return enabled ? Ink : InkOff;
        }
    }
}
